SELECT CASE WHEN d.budget >= 3340000 THEN 'high' WHEN d.budget >= 713000 THEN 'mid' ELSE 'low' END AS budget_bucket, AVG(e.salary) AS avg_salary, SUM(CASE WHEN e.job_title = 'Manager' THEN e.salary ELSE 0 END) AS manager_salary FROM employees e INNER JOIN departments d ON e.dept_id = d.id WHERE d.location != 'London' GROUP BY CASE WHEN d.budget >= 3340000 THEN 'high' WHEN d.budget >= 713000 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN e.job_title = 'Manager' THEN e.salary ELSE 0 END) >= 73 ORDER BY budget_bucket;
